def bellman_ford(es: list, s: int, inf: int) -> list:
    n = 0
    for e in es: n = max(n, e[0], e[1])
    n += 1
    dis = [inf] * n
    dis[s] = 0
    for t in range(n << 1):
        for e in es:
            if dis[e[0]] != inf and dis[e[1]] > dis[e[0]] + e[2]:
                dis[e[1]] = dis[e[0]] + e[2]
                if t + 1 >= n: dis[e[1]] = -inf
    return dis

