    if memo[k] != -1:
        return memo[k]
    elif not connected[k]:
        memo[k] = 0
        return 0
    else:
        res = -1
        for point in connected[k]:
            if res < lp(point,memo,connected):
                res = lp(point,memo,connected)
        memo[k] = res+1
        return res+1

