    n, m = map(int, input().split())

    adj_list = {x: [] for x in range(1, n + 1)}

    uf = [x for x in range(n + 1)]
    sz = [1]  * (n + 1)

    def find(i):
        while uf[i] != i:
            uf[i] = uf[uf[i]]
            i = uf[i]
        return i

    def check(i, j):
        return find(i) == find(j)

    def union(i, j):
        a = find(i)
        b = find(j)
        if sz[a] < sz[b]:
            uf[a] = uf[b]
            sz[b] += sz[a]
