memo = {}
for g in range(K , 0 , -1):
    comb = mod_pow(K // g , N)
    for j in range(2 , K // g + 1):
        comb = (comb - memo[j * g] + MOD) % MOD
    memo[g] = comb
    result = (result + comb * g) % MOD
print(result)

