def track(A, n, k, P): # 最大積載量Pを決めた時，何個の荷物を載せることができるかを返す
	i = 0
	for _ in range(k):
		weight_of_track_j = 0
		while weight_of_track_j + A[i] <= P:
			weight_of_track_j += A[i]
			i += 1
			if i == n:
				return n
	return i


