    for i in range(1, n+k):
        fact[i] = fact[i-1] * i

    ifact = [None] * (n+k)
    ifact[n+k-1] = fact[n+k-1] ** (-1)
    for i in range(n+k-2, -1, -1):
        ifact[i] = ifact[i+1] * (i+1)

    p = [Bigint(1)] * (k+1)
    q = [Bigint(1)] * (k+1)
    for i in range(1, k+1):
        p[i] = p[i-1] * 25
