def solve(bomb):
    count = 0
    for i in range(N):
        remain = H[i] - (B*bomb)
        # まだ残ってる場合、中心爆発分で追加ダメージが必要なのでカウントする
        if remain > 0:
            additional_damage = (A-B)
            c = -(-remain // additional_damage)
            count += c

    if count <= bomb:
        return True
    else:
        return False


# leftは条件を満たす値、rightは満たさない値
def meguru(left, right):
    while abs(left - right) > 1:
        mid = (left + right) // 2;

        if (solve(mid)):
            left = mid
        else:
            right = mid;

    return left


