def isPacked(numcar, maxweight, packs):
	weight = 0  # 一台当たりの積載量
	k = 1  # トラック台数

	for j in range(len(packs)):
		if packs[j] > maxweight:
			return False
		if weight + packs[j] > maxweight:
			k = k + 1
			weight = packs[j]
		else:
			weight = weight + packs[j]
		if k > numcar:
			return False

	return True


