    # ビンゴカードに配置する数字を決定
    def __decision(self):
        while len(self.li) < 25:  # 数字が25個になるまで
            rnd = random.randint(1, 75)  # 1～75の乱数を生成
            if self.li.count(rnd) == 0:  # 生成された乱数がlistに存在しなければ追加
                self.li.append(rnd)
