                    or len([j for j in self.li if j <= 45 and not j <= 30]) > 5 \
                    or len([j for j in self.li if j <= 60 and not j <= 45]) > 5 \
                    or len([j for j in self.li if j <= 75 and not j <= 60]) > 5:
                self.li.remove(rnd)
        self.li.sort()

    # ビンゴカード(2次元配列)に数字を配置
    def set(self):
        self.__decision()
        index = 0
        for i in range(5):
            for j in range(5):
                if i == 2 and j == 2:
                    self.bingo[j][i] = 'free'
                    index += 1
                else:
                    self.bingo[j][i] = str(self.li[index])
                    index += 1
        self.bingo_state[2][2] = 1
        self.li.pop(12)

    # 抽選
    def __lottery(self):
        rnd = self.num[random.randint(0, len(self.num) - 1)]
        self.num.remove(rnd)
        self.lot.append(rnd)

    # 判定
    def __judge(self):
        # 抽選数字の有無の判定
        self.__lottery()
        number = self.lot[-1]
        if self.li.count(number) == 1:
            for i in range(5):
                for j in range(5):
                    if self.bingo[i][j] == str(number):
                        self.bingo_state[i][j] = 1
                        self.counter += 1
                        self.latest_i = i
                        self.latest_j = j
                        break
                else:
                    continue
                break
            if self.counter >= 4:
                # ビンゴの有無の判定

                # 縦
                for i in range(5):
                    if self.bingo_state[i][self.latest_j] == 0:
                        break
                    elif i == 4:
                        self.flag = 1

                # 横
                if self.flag == 0:
                    for j in range(5):
                        if self.bingo_state[self.latest_i][j] == 0:
                            break
                        elif j == 4:
                            self.flag = 1

                # 斜め
                if self.flag == 0:
                    if self.latest_i == self.latest_j:
                        for i in range(5):
                            if self.bingo_state[i][i] == 0:
                                break
                            elif i == 4:
