                    elif self.latest_i + self.latest_j == 4:
                        ii = 0
                        jj = 4
                        for _ in range(5):
                            if self.bingo_state[ii][jj] == 0:
                                break
                            elif ii == 4 and jj == 0:
                                self.flag = 1
                            ii += 1
                            jj -= 1

    # ビンゴにかかった回数を返すよ
    def get(self):
        while self.flag == 0:
            self.__judge()
        return len(self.lot)


