def solve(S: str):
    dp = [[0] * 5 for _ in range(len(S) + 1)]
    dp[0][1] = 1

    for i, s in enumerate(S):
        for j, a in enumerate('_ABC', 1):
            dp[i+1][j] = (3 * dp[i][j]) if s == '?' else dp[i][j]
            if s == a or s == '?':
                dp[i+1][j] += dp[i][j-1]
            dp[i+1][j] %= MOD
    return dp[-1][-1] % MOD


