def insersionSort(A, N, count=0, g=1):
    # 間隔 g で挿入ソートを行う
    for i in range(g, N):
        v = A[i]
        j = i - g 
        while j >= 0 and A[j] > v:
            A[j+g] = A[j]
            j -= g
            count += 1
        A[j+g] = v

    return A, count

