def prime_factorization(n):
    #nを素因数分解して、昇順のリストを返す
    m=n
    ans = []
    p = 2

    while p<m**0.5:
        if n%p == 0:
            ans.append(p)
            while n%p==0:
                n /= p
        else:
            p += 1

    if n!=1:
        ans.append(int(n))

    return ans

