class BIT:
    def __init__(self, n):
        self.n = n
        self.data = [0] * (n + 1)

    def total(self, i):
        res = 0
        while i:
            res += self.data[i]
            i -= i & -i
        return res

    def add(self, i, val):
        while i <= self.n:
            self.data[i] += val
            i += i & -i


