def fun(A,n,m):
    dp = list2d(n,m,0)
    for i in range(1,n): #initialising reachable first row
        if A[i][0]== '.':
            dp[i][0] = 1
        else:
            break
    for j in range(1,m): #initialising reachable first column
        if A[0][j] == '.':
            dp[0][j] = 1
        else:
            break
    dp[0][0] = 1
    for i in range(1,n):
        for j in range(1,m):
            if A[i][j] == "#":
                dp[i][j] = 0
                continue
            if A[i-1][j] == '.':
                dp[i][j] += dp[i-1][j]
                dp[i][j] %= MOD
            if A[i][j-1] == '.':
                dp[i][j] += dp[i][j-1]
                dp[i][j] %= MOD
    return int(dp[n-1][m-1])

