def distance(length,x,y,n):
    D = 0
    for i in range(length):
        D += fabs(x[i]-y[i]) ** n
    return pow(D,1.0/n)

def che_distance(length,x,y):
    D = 0
    for i in range(length):
        if D < fabs(x[i]-y[i]):
            D = fabs(x[i]-y[i])
    return D

