def insertion_sort(A, n, g):
    c = 0
    for i in range(g, n):
        v = A[i]
        j = i - g
        while j >= 0 and A[j] > v:
            A[j + g] = A[j]
            j = j - g
            c += 1
        A[j + g] = v
    return c

def shell_sort(A, n):
    G = sorted(iter_g(n), reverse=True)
    c = 0
    for g in G:
        c += insertion_sort(A, n, g)
    return A, c, G

def iter_g(n):
    v = 1
    d = 3
    while v <= n:
        yield v
        v += d
        d *= 3

