def z_algo(s):
    n = len(s)
    LCP = [0]*n
    c = 0 #最も末尾側までLCPを求めたindex
    for i in range(1, n): # i番目からのLCPが以前計算したcからのLCPに含まれている場合
        if i+LCP[i-c] < c+LCP[c]:
            LCP[i] = LCP[i-c]
        else:
            j = max(0, c+LCP[c]-i)
            while i+j < n and s[j] == s[i+j]:
                j += 1
            LCP[i] = j
            c = i
    LCP[0] = n
    return LCP


