def shell_sort(data, gaps):
    o = 0;
    for gap in gaps:
        for g in range(gap):
            o += insert_sort(data, gap, g);
    return o;

def insert_sort(data, gap, g):
    o = 0;
    count = len(data);
    for i in range(g + gap, count, gap):
        n = data[i];
        j = i - gap;
        while j >= 0:
            if data[j] > n:
                o += 1;
                data[j + gap] = data[j];
                j -= gap;
            else:
                break;
        data[j + gap] = n;
    return o;

