  for i in range(m):
    b_cum_sum[i+1] = b_cum_sum[i] + b_books[i]
  current = 0
  ans = 0
  for i in range(n+1):
    if i > 0:
      current += a_books[i-1]
    if current > k:
      break
    rest = k - current
    index = binary_search(b_cum_sum, rest)
    ans = max(ans, i+index-1)
  print(ans)

