def dfs_iter(n):
    stack = [n]
    ans = 0
    while stack:
        node = stack.pop()
        if not visited[node]:
            visited[node] = True
            ans += 1
            for child in adj[node]:
                if not visited[child]:
                    stack.append(child)
    return ans

