        if(start==0):
            obj=self.letter[end::-1]
            self.memory=obj+self.letter[(end+1):]
        else:
            obj=self.letter[end:(start-1):-1]
            self.memory=self.letter[0:start]+obj+self.letter[(end+1):]
        self.letter=self.memory
    def check(self):
