def sel_sort(A, N):
    ''' 選択ソート '''
    count = 0
    for n in range(N):
        minm = n
        for m in range(n, N):
            if A[m] < A[minm]:
                minm = m

        if minm != n:
            A[n], A[minm] = A[minm], A[n]
            count += 1

    return (A, count)


