    for i in range(10):
        for j in range(10):
            for k in range(10):
                c_lsit_list[j][k] = min(
                    c_lsit_list[j][i] + c_lsit_list[i][k],
                    c_lsit_list[j][k]
                )
    min_c_list = [c_lsit_list[i][1] for i in range(10)]
    return min_c_list

