import sys


def solve(N: int, P: "List[int]"):
    sorted_lis = sorted([(n, i) for i, n in enumerate(P)])
    max_con = 1
    con_cnt = 0
    pre_idx = N
    for _, i in sorted_lis:
        if i > pre_idx:
            con_cnt += 1
        else:
            max_con = max(max_con, con_cnt)
            con_cnt = 1
        pre_idx = i
    max_con = max(max_con, con_cnt)
    print(N - max_con)
    return


