    sw = 0
    flag = True
    while flag:
        flag = False
        for j in reversed(range(1, N)):
            if  A[j - 1] > A[j]:
                A[j - 1],   A[j] = A[j], A[j - 1]
                sw += 1
                flag = True
    return sw

