    ans -= comb(w + a - 2, w - 1)
else:

    memo = [1] * b
    for i in range(1, b):
        memo[i] = (memo[i - 1] * (h - a + i) * inv(i)) % M

    memo2 = [0] * b
    height = a - 1
    width = w - b
    memo2[b - 1] = comb(height + width, height)
    for i in range(1, b):
        memo2[b - i - 1] = (memo2[b - i] * (height + width + i) * inv(width + i)) % M

    ans -= memo[0] * memo2[0]
    ans %= M
    for i in range(1, b):
        ans -= (memo[i] - memo[i - 1]) * memo2[i]
        ans %= M

print(ans % M)

