def make_divisors(n):
    divisors = []
    for i in range(1, int(n**0.5)+1):
        if ((n % i == 0)):
            if(i>1):
                divisors.append(i)
            if i != n // i:
                if(n//i>1):
                    divisors.append(n//i)
    return divisors

