def PrimeFactorization(n):
    ret = []
    for i in range(2, int(n ** 0.5)+1):
        if n % i != 0:
            continue

        exp = 0
        while n % i == 0:
            exp += 1
            ret.append(i**exp)
            n //= i

    if n != 1:
        ret.append(n)

    ret.sort()
    return ret

